//! Authoritative clinical commands. Context is supplied by a trusted host,
//! never deserialized from a request or reconstructed from a cached summary.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::{AppServices, domain::*, session::Principal};

pub struct ClinicalContext {
    pub identity_id: Uuid,
    pub actor: ActorId,
    pub practice: PracticeId,
    pub principal: Principal,
    pub expires_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum GateAction {
    Affirm,
    Remove,
}

/// Transport input. Actor, principal and practice authority never come from it.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct GateMutation {
    pub command_id: Uuid,
    pub kind: GateAffirmationKind,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct GateCommand {
    pub command_id: Uuid,
    pub case_id: Uuid,
    pub kind: GateAffirmationKind,
    pub action: GateAction,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct GateSnapshot {
    pub case_id: Uuid,
    pub affirmed: Vec<GateAffirmationKind>,
    pub gate_affirmed_at: Option<DateTime<Utc>>,
    pub gate_affirmed_by: Option<Uuid>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct GateCommandResult {
    pub command_id: Uuid,
    pub case_id: Uuid,
    pub kind: GateAffirmationKind,
    pub action: GateAction,
    pub gate: GateSnapshot,
    pub committed_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum GateError {
    #[error("authentication required")]
    Unauthenticated,
    #[error("gate access denied")]
    Denied,
    #[error("gate or command not found")]
    NotFound,
    #[error("command identifier already has a different payload")]
    CommandConflict,
    #[error("gate command service unavailable")]
    Unavailable,
    #[error("native authentication unavailable")]
    NativeAuthenticationUnavailable,
}

impl AppServices {
    fn check_clinical_context(&self, context: &ClinicalContext) -> Result<(), GateError> {
        if context.expires_at <= self.clock.now() {
            return Err(GateError::Unauthenticated);
        }
        if context.principal != Principal::User {
            return Err(GateError::Denied);
        }
        Ok(())
    }

    /// A separate service check precedes the database's independent control.
    /// An uncertain response is reconciled by command ID, never automatic replay.
    pub async fn execute_gate_command(
        &self,
        context: &ClinicalContext,
        command: &GateCommand,
    ) -> Result<GateCommandResult, GateError> {
        self.check_clinical_context(context)?;
        if let Some(original) = self.cases.lookup_gate_command(context, command.command_id).await?
            && (original.case_id != command.case_id
                || original.kind != command.kind
                || original.action != command.action)
        {
            return Err(GateError::CommandConflict);
        }
        if !self.authority.may_affirm_gate(context, command.case_id).await? {
            return Err(GateError::Denied);
        }
        self.check_clinical_context(context)?;
        self.cases.execute_gate_command(context, command).await
    }

    pub async fn read_verified_gate(
        &self,
        context: &ClinicalContext,
        case_id: Uuid,
    ) -> Result<GateSnapshot, GateError> {
        self.check_clinical_context(context)?;
        self.cases.read_verified_gate(context, case_id).await
    }

    pub async fn lookup_gate_command(
        &self,
        context: &ClinicalContext,
        command_id: Uuid,
    ) -> Result<Option<GateCommandResult>, GateError> {
        self.check_clinical_context(context)?;
        self.cases.lookup_gate_command(context, command_id).await
    }
}

//! Session authority shared by every shell. Credentials never serialize.

use std::sync::Arc;

use async_trait::async_trait;
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::{
    domain::{ActorId, PracticeId},
    ports::Clock,
};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Principal {
    User,
    Agent,
    Service,
}

#[derive(Debug, Clone)]
pub struct VerifiedSession {
    pub actor: ActorId,
    pub practice: PracticeId,
    pub principal: Principal,
    pub on_behalf_of: Option<ActorId>,
}

impl VerifiedSession {
    pub fn may_attempt_clinical_act(&self) -> bool {
        matches!(self.principal, Principal::User)
    }
}

/// Opaque input accepted only by the trusted identity adapter. No Debug or
/// Serialize implementation: logging a request must not disclose a credential.
pub enum SessionCredential {
    Cookie(String),
    NativeToken(String),
}

/// Produced by server-side whoami validation, never from caller identity hints.
pub struct AuthenticatedIdentity {
    pub identity_id: Uuid,
    pub session_id: Uuid,
    /// Set by the trusted identity adapter, never by a request header or trait.
    pub principal: Principal,
    pub expires_at: DateTime<Utc>,
}

pub struct Membership {
    pub user_id: Uuid,
    pub practice_id: Uuid,
    pub display_name: String,
    pub capabilities: Vec<String>,
    pub authorization_revision: String,
}

/// A noncredential projection. It grants no authority to subsequent commands.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SessionSummary {
    pub identity_id: Uuid,
    pub user_id: Uuid,
    pub practice_id: Uuid,
    pub display_name: String,
    pub principal: Principal,
    pub capabilities: Vec<String>,
    pub expires_at: DateTime<Utc>,
    pub authorization_revision: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum SessionError {
    #[error("authentication required")]
    Unauthenticated,
    #[error("additional authentication required")]
    ReauthenticationRequired,
    #[error("practice access denied")]
    PracticeDenied,
    #[error("session service unavailable")]
    Unavailable,
    #[error("native authentication unavailable")]
    NativeAuthenticationUnavailable,
}

#[async_trait]
pub trait IdentityProvider: Send + Sync {
    async fn authenticate(
        &self,
        credential: &SessionCredential,
    ) -> Result<AuthenticatedIdentity, SessionError>;
}

#[async_trait]
pub trait MembershipRepository: Send + Sync {
    async fn resolve(
        &self,
        identity: &AuthenticatedIdentity,
        practice: Option<Uuid>,
    ) -> Result<Membership, SessionError>;
}

#[async_trait]
pub trait SessionPort: Send + Sync {
    async fn resolve(
        &self,
        credential: &SessionCredential,
        practice: Option<Uuid>,
    ) -> Result<SessionSummary, SessionError>;
}

pub struct SessionService {
    pub identities: Arc<dyn IdentityProvider>,
    pub memberships: Arc<dyn MembershipRepository>,
    pub clock: Arc<dyn Clock>,
}

#[async_trait]
impl SessionPort for SessionService {
    async fn resolve(
        &self,
        credential: &SessionCredential,
        practice: Option<Uuid>,
    ) -> Result<SessionSummary, SessionError> {
        let identity = self.identities.authenticate(credential).await?;
        if identity.expires_at <= self.clock.now() {
            return Err(SessionError::Unauthenticated);
        }
        if identity.principal != Principal::User {
            return Err(SessionError::PracticeDenied);
        }
        let membership = self.memberships.resolve(&identity, practice).await?;
        // A slow database read cannot extend the validated credential's life.
        if identity.expires_at <= self.clock.now() {
            return Err(SessionError::Unauthenticated);
        }
        Ok(SessionSummary {
            identity_id: identity.identity_id,
            user_id: membership.user_id,
            practice_id: membership.practice_id,
            display_name: membership.display_name,
            principal: identity.principal,
            capabilities: membership.capabilities,
            expires_at: identity.expires_at,
            authorization_revision: membership.authorization_revision,
        })
    }
}

/// Clean-checkout composition refuses authenticated session work until configured.
pub struct UnavailableSessions;

#[async_trait]
impl SessionPort for UnavailableSessions {
    async fn resolve(
        &self,
        _: &SessionCredential,
        _: Option<Uuid>,
    ) -> Result<SessionSummary, SessionError> {
        Err(SessionError::Unavailable)
    }
}

use super::*;
use aso_host::{AppServices, domain::*, ports::*, session::{AuthenticatedIdentity, IdentityProvider, Membership, MembershipRepository, SessionCredential, SessionError, SessionPort, SessionService, SessionSummary}};
use async_trait::async_trait;
use axum::{body::{Body, to_bytes}, http::Request};
use chrono::{DateTime, Duration, Utc};
use serde_json::Value;
use std::sync::{Arc, Mutex, atomic::{AtomicUsize, Ordering}};
use tower::ServiceExt;

fn now() -> DateTime<Utc> { "2026-09-06T12:00:00Z".parse().unwrap() }
fn id(value: u128) -> Uuid { Uuid::from_u128(value) }
fn summary() -> SessionSummary {
    SessionSummary {
        identity_id: id(1), user_id: id(2), practice_id: id(3),
        display_name: "Synthetic Router Surgeon".into(), principal: Principal::User,
        capabilities: vec!["affirm_gate".into()], expires_at: now() + Duration::hours(1),
        authorization_revision: "synthetic:1".into(),
    }
}
fn snapshot(case_id: Uuid) -> GateSnapshot {
    GateSnapshot { case_id, affirmed: vec![], gate_affirmed_at: None, gate_affirmed_by: None }
}
fn result(case_id: Uuid, command_id: Uuid) -> GateCommandResult {
    GateCommandResult { command_id, case_id, kind: GateAffirmationKind::Policy,
        action: GateAction::Affirm, gate: snapshot(case_id), committed_at: now() }
}

struct Sessions {
    response: Mutex<Result<SessionSummary, SessionError>>,
    // Synthetic credentials only, confined to this test fixture.
    requests: Mutex<Vec<(String, Option<Uuid>)>>,
}

struct AgentIdentity;
#[async_trait]
impl IdentityProvider for AgentIdentity {
    async fn authenticate(&self, _: &SessionCredential) -> Result<AuthenticatedIdentity, SessionError> {
        Ok(AuthenticatedIdentity {
            identity_id: id(1),
            session_id: id(9),
            principal: Principal::Agent,
            expires_at: now() + Duration::hours(1),
        })
    }
}

struct AcceptingMemberships { calls: AtomicUsize }
#[async_trait]
impl MembershipRepository for AcceptingMemberships {
    async fn resolve(&self, _: &AuthenticatedIdentity, _: Option<Uuid>) -> Result<Membership, SessionError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        Ok(Membership {
            user_id: id(2), practice_id: id(3), display_name: "Synthetic Agent".into(),
            capabilities: vec!["affirm_gate".into()], authorization_revision: "synthetic:agent".into(),
        })
    }
}
#[async_trait]
impl SessionPort for Sessions {
    async fn resolve(&self, credential: &SessionCredential, practice: Option<Uuid>)
        -> Result<SessionSummary, SessionError> {
        let credential = match credential {
            SessionCredential::Cookie(value) => format!("cookie:{value}"),
            SessionCredential::NativeToken(value) => format!("native:{value}"),
        };
        self.requests.lock().unwrap().push((credential, practice));
        self.response.lock().unwrap().clone()
    }
}

#[derive(Debug, PartialEq)]
struct ObservedContext {
    identity_id: Uuid, actor: ActorId, practice: PracticeId,
    principal: Principal, expires_at: DateTime<Utc>,
}
impl From<&ClinicalContext> for ObservedContext {
    fn from(context: &ClinicalContext) -> Self {
        Self { identity_id: context.identity_id, actor: context.actor, practice: context.practice,
            principal: context.principal, expires_at: context.expires_at }
    }
}
struct Cases {
    reads: AtomicUsize,
    commands: Mutex<Vec<(ObservedContext, GateCommand)>>,
    read_error: Mutex<Option<GateError>>,
    command_error: Mutex<Option<GateError>>,
    lookup: Mutex<Option<GateCommandResult>>,
}
#[async_trait]
impl CaseRepository for Cases {
    async fn read_verified_gate(&self, _: &ClinicalContext, case: Uuid) -> Result<GateSnapshot, GateError> {
        self.reads.fetch_add(1, Ordering::SeqCst);
        if let Some(error) = *self.read_error.lock().unwrap() { return Err(error); }
        Ok(snapshot(case))
    }
    async fn execute_gate_command(&self, context: &ClinicalContext, command: &GateCommand)
        -> Result<GateCommandResult, GateError> {
        self.commands.lock().unwrap().push((context.into(), command.clone()));
        if let Some(error) = *self.command_error.lock().unwrap() { return Err(error); }
        let mut response = result(command.case_id, command.command_id);
        response.kind = command.kind;
        response.action = command.action;
        Ok(response)
    }
    async fn lookup_gate_command(&self, _: &ClinicalContext, _: Uuid)
        -> Result<Option<GateCommandResult>, GateError> { Ok(self.lookup.lock().unwrap().clone()) }
    async fn gate_state(&self, _: CaseId) -> Result<GateState, DomainError> { panic!("legacy read") }
    async fn record_affirmation(&self, _: CaseId, _: GateAffirmationKind, _: ActorId, _: DateTime<Utc>)
        -> Result<GateState, DomainError> { panic!("legacy write") }
}

struct Authority { allow: Mutex<Result<bool, GateError>>, calls: AtomicUsize }
#[async_trait]
impl AuthorityPort for Authority {
    async fn may_affirm_gate(&self, _: &ClinicalContext, _: Uuid) -> Result<bool, GateError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        *self.allow.lock().unwrap()
    }
    async fn holds(&self, _: ActorId, _: Capability) -> Result<bool, DomainError> { panic!("legacy authority") }
}
struct Unused;
impl Clock for Unused { fn now(&self) -> DateTime<Utc> { now() } }
#[async_trait]
impl EvidenceRepository for Unused {
