    async fn sign(&self, _: LetterId, _: ActorId, _: DateTime<Utc>) -> Result<Letter, DomainError> { panic!("sign") }
}

struct Fixture { app: Router, sessions: Arc<Sessions>, cases: Arc<Cases>, authority: Arc<Authority> }
impl Fixture {
    fn new() -> Self {
        let sessions = Arc::new(Sessions { response: Mutex::new(Ok(summary())), requests: Mutex::new(vec![]) });
        let cases = Arc::new(Cases { reads: AtomicUsize::new(0), commands: Mutex::new(vec![]),
            read_error: Mutex::new(None), command_error: Mutex::new(None), lookup: Mutex::new(None) });
        let authority = Arc::new(Authority { allow: Mutex::new(Ok(true)), calls: AtomicUsize::new(0) });
        let unused = Arc::new(Unused);
        let services = Arc::new(AppServices { sessions: sessions.clone(), cases: cases.clone(), authority: authority.clone(),
            evidence: unused.clone(), criteria: unused.clone(), letters: unused.clone(), clock: unused });
        Self { app: crate::api_router(ServerState { services }), sessions, cases, authority }
    }
    async fn request(&self, method: &str, uri: &str, body: Value) -> Response {
        self.raw(method, uri, &body.to_string(), &[("Authorization", "Bearer synthetic-router-token")]).await
    }
    async fn raw(&self, method: &str, uri: &str, body: &str, headers: &[(&str, &str)]) -> Response {
        let mut request = Request::builder().method(method).uri(uri).header("Content-Type", "application/json");
        for (name, value) in headers { request = request.header(*name, *value); }
        let response = self.app.clone().oneshot(request.body(Body::from(body.to_owned())).unwrap()).await.unwrap();
        assert_eq!(response.headers().get(header::CACHE_CONTROL).unwrap(), "no-store");
        assert_eq!(response.headers().get(header::VARY).unwrap(), "Cookie, Authorization, X-Session-Token");
        response
    }
    async fn policy(&self, method: &str, uri: &str) -> Response {
        self.request("POST", "/internal/gate/authorize", json!({"method":method,"uri":uri})).await
    }
    fn no_commands(&self) { assert!(self.cases.commands.lock().unwrap().is_empty()); }
}
async fn expect_error(response: Response, status: StatusCode, code: &str) {
    assert_eq!(response.status(), status);
    let body = to_bytes(response.into_body(), 4096).await.unwrap();
    assert_eq!(serde_json::from_slice::<Value>(&body).unwrap(), json!({"error":code}));
}
fn mutation() -> Value { json!({"commandId":id(5),"kind":"policy"}) }
fn gate() -> String { format!("/api/cases/{}/gate", id(4)) }

#[tokio::test]
async fn each_command_resolves_fresh_context_and_ignores_identity_headers() {
    let fixture = Fixture::new();
    let selected = id(30);
    for (index, operation) in ["affirm", "remove"].into_iter().enumerate() {
        let mut current = summary();
        current.identity_id = id(100 + index as u128);
        current.user_id = id(200 + index as u128);
        current.practice_id = selected;
        *fixture.sessions.response.lock().unwrap() = Ok(current.clone());
        let uri = format!("{}/{operation}?practiceId={selected}", gate());
        let response = fixture.raw("POST", &uri, &mutation().to_string(), &[
            ("Authorization", "Bearer synthetic-router-token"), ("X-User-Id", "forged-user"),
            ("X-Practice-Id", "forged-practice"), ("X-Flint-User-Id", "forged-identity"),
            ("X-Flint-Principal-Type", "Agent"), ("X-Role", "administrator"),
        ]).await;
        assert_eq!(response.status(), StatusCode::OK);
        let commands = fixture.cases.commands.lock().unwrap();
        assert_eq!(commands[index].0, ObservedContext { identity_id: current.identity_id,
            actor: ActorId(current.user_id), practice: PracticeId(selected), principal: Principal::User,
            expires_at: current.expires_at });
        assert_eq!(commands[index].1.command_id, id(5));
        assert_eq!(commands[index].1.case_id, id(4));
        assert_eq!(commands[index].1.kind, GateAffirmationKind::Policy);
        assert_eq!(commands[index].1.action, if index == 0 { GateAction::Affirm } else { GateAction::Remove });
    }
    assert_eq!(*fixture.sessions.requests.lock().unwrap(), vec![
        ("native:synthetic-router-token".into(), Some(selected)),
        ("native:synthetic-router-token".into(), Some(selected)),
    ]);
    assert_eq!(fixture.authority.calls.load(Ordering::SeqCst), 2);
}

#[tokio::test]
async fn expiry_and_nonhuman_principals_are_denied_with_accepting_downstream_ports() {
    for (principal, expired, status, code) in [
        (Principal::User, true, StatusCode::UNAUTHORIZED, "unauthenticated"),
        (Principal::Agent, false, StatusCode::FORBIDDEN, "gate_denied"),
        (Principal::Service, false, StatusCode::FORBIDDEN, "gate_denied"),
    ] {
        let fixture = Fixture::new();
        let mut session = summary();
        session.principal = principal;
        if expired { session.expires_at = now(); }
        *fixture.sessions.response.lock().unwrap() = Ok(session);
        for operation in ["affirm", "remove"] {
            expect_error(fixture.request("POST", &format!("{}/{operation}", gate()), mutation()).await, status, code).await;
            expect_error(fixture.policy("POST", &format!("{}/{operation}", gate())).await, status, code).await;
        }
        expect_error(fixture.request("GET", &gate(), Value::Null).await, status, code).await;
        expect_error(fixture.policy("GET", &gate()).await, status, code).await;
        fixture.no_commands();
        assert_eq!(fixture.cases.reads.load(Ordering::SeqCst), 0);
        assert_eq!(fixture.authority.calls.load(Ordering::SeqCst), 0);
    }
}

#[tokio::test]
async fn policy_checks_fresh_capability_without_calling_service_authority_or_commands() {
    let fixture = Fixture::new();
    // The callback must allow an authorized human even when AppServices authority would deny.
    *fixture.authority.allow.lock().unwrap() = Ok(false);
    assert_eq!(fixture.policy("POST", &format!("{}/affirm", gate())).await.status(), StatusCode::NO_CONTENT);
    let mut admin = summary();
    admin.capabilities = vec!["configure".into(), "view_audit".into()];
    *fixture.sessions.response.lock().unwrap() = Ok(admin);
    for operation in ["affirm", "remove"] {
        expect_error(fixture.policy("POST", &format!("{}/{operation}", gate())).await,
            StatusCode::FORBIDDEN, "gate_denied").await;
    }
    assert_eq!(fixture.policy("GET", &gate()).await.status(), StatusCode::NO_CONTENT);
    assert_eq!(fixture.sessions.requests.lock().unwrap().len(), 4);
    assert_eq!(fixture.cases.reads.load(Ordering::SeqCst), 2);
    assert_eq!(fixture.authority.calls.load(Ordering::SeqCst), 0);
    fixture.no_commands();
}

#[tokio::test]
async fn service_authority_denies_after_independent_policy_allows() {
    let fixture = Fixture::new();
    *fixture.authority.allow.lock().unwrap() = Ok(false);
    assert_eq!(fixture.policy("POST", &format!("{}/affirm", gate())).await.status(), StatusCode::NO_CONTENT);
    expect_error(fixture.request("POST", &format!("{}/affirm", gate()), mutation()).await,
        StatusCode::FORBIDDEN, "gate_denied").await;
    assert_eq!(fixture.authority.calls.load(Ordering::SeqCst), 1);
    fixture.no_commands();
}

#[tokio::test]
async fn policy_propagates_case_scope_denial_and_backend_unavailability() {
    let fixture = Fixture::new();
    for (error, status, code) in [
        (GateError::Denied, StatusCode::FORBIDDEN, "gate_denied"),
        (GateError::NotFound, StatusCode::NOT_FOUND, "gate_not_found"),
        (GateError::Unavailable, StatusCode::SERVICE_UNAVAILABLE, "gate_unavailable"),
    ] {
        *fixture.cases.read_error.lock().unwrap() = Some(error);
        expect_error(fixture.policy("POST", &format!("{}/affirm", gate())).await, status, code).await;
    }
    assert_eq!(fixture.authority.calls.load(Ordering::SeqCst), 0);
    fixture.no_commands();
}

#[tokio::test]
async fn mutation_requires_command_id_and_kind_and_rejects_injected_actor() {
    let fixture = Fixture::new();
    for body in [json!({"kind":"policy"}), json!({"commandId":id(5)}),
        json!({"commandId":id(5),"kind":"policy","actor":id(90)}),
        json!({"commandId":id(5),"kind":"policy","principal":"user"}),
        json!({"commandId":id(5),"kind":"policy","practiceId":id(3)}),
        json!({"commandId":id(5),"kind":"unknown"})] {
        expect_error(fixture.request("POST", &format!("{}/affirm", gate()), body).await,
            StatusCode::BAD_REQUEST, "invalid_gate_request").await;
    }
    assert!(fixture.sessions.requests.lock().unwrap().is_empty());
    fixture.no_commands();
}

#[tokio::test]
async fn malformed_path_query_and_json_are_sanitized_and_never_cached() {
    let fixture = Fixture::new();
    for uri in ["/api/cases/not-a-uuid/gate/affirm".into(),
        format!("{}/affirm?practiceId=not-a-uuid", gate()),
        format!("{}/affirm?role=surgeon", gate()),
        format!("{}/affirm?practiceId={}&practiceId={}", gate(), id(3), id(30))] {
        expect_error(fixture.request("POST", &uri, mutation()).await,
            StatusCode::BAD_REQUEST, "invalid_gate_request").await;
    }
    expect_error(fixture.raw("POST", &format!("{}/affirm", gate()), "{invalid", &[
        ("Authorization", "Bearer synthetic-router-token")]).await,
        StatusCode::BAD_REQUEST, "invalid_gate_request").await;
    expect_error(fixture.request("GET", &format!("{}/commands/not-a-uuid", gate()), Value::Null).await,
        StatusCode::BAD_REQUEST, "invalid_gate_request").await;
    for uri in [format!("https://untrusted.invalid{}/affirm", gate()),
        format!("{}/affirm?practiceId=bad", gate()), "/api/cases/bad/gate/affirm".into(),
        format!("{}/commands/bad", gate())] {
        expect_error(fixture.policy("POST", &uri).await,
            StatusCode::BAD_REQUEST, "invalid_gate_request").await;
    }
    expect_error(fixture.request("POST", "/internal/gate/authorize",
