fn mark(name: &str) { println!("gate_transaction_check: {name}"); }

fn env(name: &str) -> String {
    std::env::var(name).unwrap_or_else(|_| panic!("required fixture variable missing: {name}"))
}

fn context(value: &serde_json::Value) -> ClinicalContext {
    let id = |key| Uuid::parse_str(value[key].as_str().expect("fixture UUID missing"))
        .expect("fixture UUID invalid");
    ClinicalContext {
        identity_id: id("identity_id"), actor: ActorId(id("actor_id")),
        practice: PracticeId(id("practice_id")), principal: Principal::User,
        expires_at: Utc::now() + chrono::Duration::hours(1),
    }
}

fn command(case_id: Uuid, kind: GateAffirmationKind, action: GateAction) -> GateCommand {
    GateCommand { command_id: Uuid::new_v4(), case_id, kind, action }
}

fn services(cases: Arc<dyn CaseRepository>, authority: Arc<dyn AuthorityPort>) -> AppServices {
    AppServices {
        cases, authority, clock: Arc::new(SystemClock), sessions: Arc::new(UnavailableSessions),
        evidence: Arc::new(memory::MemoryEvidenceRepo),
        criteria: Arc::new(memory::MemoryCriteriaRepo),
        letters: Arc::new(memory::MemoryLetterRepo::default()),
    }
}

fn denied_sql<T>(result: Result<T, sqlx::Error>) {
    let error = match result { Ok(_) => panic!("forbidden SQL succeeded"), Err(error) => error };
    assert_eq!(error.as_database_error().and_then(|e| e.code()).as_deref(), Some("42501"));
}

async fn counts(pool: &PgPool, case_id: Uuid) -> (i64, i64, i64) {
    sqlx::query_as("SELECT
        (SELECT count(*) FROM aso.gate_affirmations WHERE case_id=$1),
        (SELECT count(*) FROM aso.audit_events WHERE case_id=$1 AND action LIKE 'gate.%'),
        (SELECT count(*) FROM aso.gate_commands WHERE case_id=$1)")
        .bind(case_id).fetch_one(pool).await.expect("fixture counts failed")
}

async fn trigger_transaction(
    observer: &PgPool,
    caller: &ClinicalContext,
    disable_authority: bool,
) -> Transaction<'static, Postgres> {
    let mut tx = observer.begin().await.expect("trigger probe transaction failed");
    if disable_authority {
        sqlx::query("ALTER TABLE aso.gate_affirmations DISABLE TRIGGER gate_affirmations_authority")
            .execute(&mut *tx).await.expect("authority mutation setup failed");
    }
    // Only the disposable observer can assume this role. Direct table DML here
    // bypasses apply_gate_command and proves the trigger has its own control.
    sqlx::query("SET LOCAL ROLE aso_gate_owner").execute(&mut *tx).await
        .expect("trigger probe owner setup failed");
    let principal = match caller.principal {
        Principal::User => "user", Principal::Agent => "agent", Principal::Service => "service",
    };
    sqlx::query("SELECT set_config('aso.kratos_identity_id',$1,true),
        set_config('aso.actor_id',$2,true), set_config('aso.practice_id',$3,true),
        set_config('aso.principal',$4,true), set_config('aso.session_expires_at',$5,true)")
        .bind(caller.identity_id.to_string()).bind(caller.actor.to_string())
        .bind(caller.practice.to_string()).bind(principal).bind(caller.expires_at.to_rfc3339())
        .execute(&mut *tx).await.expect("trigger probe context setup failed");
    tx
}

