    let complete = app.read_verified_gate(&a, case_id).await.expect("gate read failed");
    assert_eq!(complete.affirmed.len(), 4);
    assert!(complete.gate_affirmed_at.is_some());
    assert_eq!(complete.gate_affirmed_by, Some(a.actor.0));
    let removed = app.execute_gate_command(&b, &command(case_id, GateAffirmationKind::Plan, GateAction::Remove))
        .await.expect("second surgeon removal failed");
    assert_eq!(removed.gate.affirmed.len(), 3);
    assert_eq!(removed.gate.gate_affirmed_at, None);
    assert_eq!(removed.gate.gate_affirmed_by, None);
    assert_eq!(app.lookup_gate_command(&a, first_command.command_id).await.expect("original lookup failed"), Some(first.clone()));
    mark("derived_summary_and_original_result_survive_later_removal");

    let before_denials = counts(&observer, case_id).await;
    for caller in [&admin, &agent, &expired, &foreign] {
        assert_eq!(repository.execute_gate_command(caller, &command(case_id, GateAffirmationKind::Plan, GateAction::Affirm))
            .await, Err(GateError::Denied));
        assert_eq!(repository.execute_gate_command(caller, &command(case_id, GateAffirmationKind::Policy, GateAction::Remove))
            .await, Err(GateError::Denied));
    }
    assert_eq!(repository.execute_gate_command(&a, &command(foreign_case, GateAffirmationKind::Plan, GateAction::Affirm))
        .await, Err(GateError::Denied));
    assert_eq!(repository.read_verified_gate(&a, foreign_case).await, Err(GateError::Denied));
    assert_eq!(counts(&observer, case_id).await, before_denials);
    mark("database_independently_refuses_admin_agent_expiry_and_foreign_scope");

    let direct_insert = "INSERT INTO aso.gate_affirmations(case_id,kind,affirmed_by,affirmed_at)
        VALUES ($1,'plan',$2,clock_timestamp())";
    let direct_delete = "DELETE FROM aso.gate_affirmations WHERE case_id=$1 AND kind='policy'";
    for caller in [&admin, &agent, &expired, &foreign] {
        let mut tx = trigger_transaction(&observer, caller, false).await;
        let inserted = sqlx::query(direct_insert).bind(case_id).bind(caller.actor.0)
            .execute(&mut *tx).await;
        tx.rollback().await.expect("trigger insert probe rollback failed");
        denied_sql(inserted);
        let mut tx = trigger_transaction(&observer, caller, false).await;
        let deleted = sqlx::query(direct_delete).bind(case_id).execute(&mut *tx).await;
        tx.rollback().await.expect("trigger delete probe rollback failed");
        denied_sql(deleted);
    }
    // The exact statements and grants permit a verified surgeon, so blanket
    // permission refusal cannot make the negative assertions pass by accident.
    let mut tx = trigger_transaction(&observer, &a, false).await;
    let inserted = sqlx::query(direct_insert).bind(case_id).bind(a.actor.0)
        .execute(&mut *tx).await;
    tx.rollback().await.expect("trigger positive insert rollback failed");
    assert_eq!(inserted.expect("trigger positive insert control failed").rows_affected(), 1);
    let mut tx = trigger_transaction(&observer, &a, false).await;
    let deleted = sqlx::query(direct_delete).bind(case_id).execute(&mut *tx).await;
    tx.rollback().await.expect("trigger positive delete rollback failed");
    assert_eq!(deleted.expect("trigger positive delete control failed").rows_affected(), 1);
    assert_eq!(counts(&observer, case_id).await, before_denials);
    mark("authority_trigger_independently_checks_insert_and_delete");

    let mut tx = trigger_transaction(&observer, &admin, true).await;
    let unguarded = sqlx::query(direct_insert).bind(case_id).bind(admin.actor.0)
        .execute(&mut *tx).await;
    tx.rollback().await.expect("authority mutation rollback failed");
    assert_eq!(unguarded.expect("authority mutation positive control failed").rows_affected(), 1);
    let mut tx = trigger_transaction(&observer, &admin, false).await;
    let restored = sqlx::query(direct_insert).bind(case_id).bind(admin.actor.0)
        .execute(&mut *tx).await;
    tx.rollback().await.expect("restored authority probe rollback failed");
    denied_sql(restored);
    assert_eq!(counts(&observer, case_id).await, before_denials);
    mark("authority_trigger_mutation_control_restored");

    sqlx::query("INSERT INTO aso.user_roles(user_id,role_id,practice_id)
        SELECT user_id,role_id,$2 FROM aso.user_roles WHERE user_id=$1 AND practice_id=$3")
        .bind(a.actor.0).bind(foreign.practice.0).bind(a.practice.0)
        .execute(&observer).await.expect("selected practice membership setup failed");
    let mut selected = context(&contexts["A"]);
    selected.practice = foreign.practice;
    let selected_result = app.execute_gate_command(&selected,
        &command(foreign_case, GateAffirmationKind::Policy, GateAction::Affirm)).await;
    let selected_read = app.read_verified_gate(&selected, foreign_case).await;
    sqlx::query("DELETE FROM aso.user_roles WHERE user_id=$1 AND practice_id=$2")
        .bind(a.actor.0).bind(foreign.practice.0).execute(&observer).await
        .expect("selected practice membership cleanup failed");
    assert_eq!(selected_result.expect("authorized selected-practice command failed").case_id, foreign_case);
    assert_eq!(selected_read.expect("selected-practice read failed").affirmed, vec![GateAffirmationKind::Policy]);
    assert_eq!(repository.read_verified_gate(&selected, foreign_case).await, Err(GateError::Denied));
    mark("selected_practice_membership_drives_authority");

    denied_sql(sqlx::query("UPDATE aso.cases SET gate_affirmed_at=clock_timestamp(),gate_affirmed_by=$2 WHERE id=$1")
        .bind(case_id).bind(a.actor.0).execute(&repository.pool).await);
    denied_sql(sqlx::query("DELETE FROM aso.gate_affirmations WHERE case_id=$1")
        .bind(case_id).execute(&repository.pool).await);
    mark("runtime_table_writes_refused");
    denied_sql(sqlx::query("UPDATE aso.cases SET gate_affirmed_at=clock_timestamp(),gate_affirmed_by=$2 WHERE id=$1")
        .bind(case_id).bind(a.actor.0).execute(&observer).await);
    denied_sql(sqlx::query("INSERT INTO aso.cases (id,practice_id,patient_id,surgeon_id,payer_id,case_number,gate_affirmed_at,gate_affirmed_by)
        SELECT $2,practice_id,patient_id,surgeon_id,payer_id,'SYNTHETIC-FORGED',clock_timestamp(),surgeon_id FROM aso.cases WHERE id=$1")
        .bind(case_id).bind(Uuid::new_v4()).execute(&observer).await);
    denied_sql(sqlx::query("UPDATE aso.gate_commands SET result='{}'::jsonb WHERE command_id=$1")
        .bind(first_command.command_id).execute(&observer).await);
    denied_sql(sqlx::query("DELETE FROM aso.gate_commands WHERE command_id=$1")
        .bind(first_command.command_id).execute(&observer).await);
    denied_sql(sqlx::query("TRUNCATE aso.gate_commands").execute(&observer).await);
    mark("summary_guard_and_immutable_result_refuse_direct_admin_writes");

    // Remove the summary guard only inside an observer transaction, demonstrate
    // the forged write succeeds, then roll back both data and DDL immediately.
    let mut sabotage = observer.begin().await.expect("mutation transaction failed");
    sqlx::query("ALTER TABLE aso.cases DISABLE TRIGGER cases_gate_summary_guard")
        .execute(&mut *sabotage).await.expect("mutation setup failed");
    assert_eq!(sqlx::query("UPDATE aso.cases SET gate_affirmed_at=clock_timestamp(),gate_affirmed_by=$2 WHERE id=$1")
        .bind(case_id).bind(a.actor.0).execute(&mut *sabotage).await.expect("guard mutation control failed").rows_affected(), 1);
    sabotage.rollback().await.expect("mutation rollback failed");
    denied_sql(sqlx::query("UPDATE aso.cases SET gate_affirmed_at=clock_timestamp(),gate_affirmed_by=$2 WHERE id=$1")
        .bind(case_id).bind(a.actor.0).execute(&observer).await);
    mark("summary_guard_mutation_control_restored");

    let rollback_command = command(case_id, GateAffirmationKind::Plan, GateAction::Affirm);
    let before_rollback = counts(&observer, case_id).await;
    let gate_before = app.read_verified_gate(&a, case_id).await.expect("pre-rollback gate read failed");
    sqlx::raw_sql("CREATE FUNCTION aso.fixture_refuse_gate_audit() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN RAISE EXCEPTION 'synthetic audit refusal' USING ERRCODE='23514'; END $$;
        CREATE TRIGGER fixture_refuse_gate_audit BEFORE INSERT ON aso.audit_events
        FOR EACH ROW EXECUTE FUNCTION aso.fixture_refuse_gate_audit();")
        .execute(&observer).await.expect("audit failure setup failed");
    let rollback_result = app.execute_gate_command(&a, &rollback_command).await;
    sqlx::raw_sql("DROP TRIGGER fixture_refuse_gate_audit ON aso.audit_events; DROP FUNCTION aso.fixture_refuse_gate_audit();")
        .execute(&observer).await.expect("audit failure cleanup failed");
    assert_eq!(rollback_result, Err(GateError::Unavailable));
    assert_eq!(counts(&observer, case_id).await, before_rollback);
    assert_eq!(app.read_verified_gate(&a, case_id).await.expect("post-rollback gate read failed"), gate_before);
    assert_eq!(app.lookup_gate_command(&a, rollback_command.command_id).await.expect("rollback lookup failed"), None);
    app.execute_gate_command(&a, &rollback_command).await.expect("rolled-back command was not reusable");
    mark("audit_failure_rolls_back_affirmation_summary_and_result");

    let duplicate = command(case_id, GateAffirmationKind::Policy, GateAction::Affirm);
    let before_duplicate = counts(&observer, case_id).await;
    let (left, right) = tokio::join!(app.execute_gate_command(&a, &duplicate), app.execute_gate_command(&a, &duplicate));
    assert_eq!(left.expect("first concurrent duplicate failed"), right.expect("second concurrent duplicate failed"));
    let after_duplicate = counts(&observer, case_id).await;
    assert_eq!(after_duplicate, (before_duplicate.0, before_duplicate.1 + 1, before_duplicate.2 + 1));
    mark("concurrent_duplicate_commits_one_audit_and_result");

    let kinds = [GateAffirmationKind::Policy, GateAffirmationKind::Section, GateAffirmationKind::Pathway, GateAffirmationKind::Plan];
    for kind in kinds {
        app.execute_gate_command(&a, &command(case_id, kind, GateAction::Remove)).await.expect("concurrency reset failed");
    }
    let commands = kinds.map(|kind| command(case_id, kind, GateAction::Affirm));
    let (one, two, three, four) = tokio::join!(
        app.execute_gate_command(&a, &commands[0]), app.execute_gate_command(&b, &commands[1]),
        app.execute_gate_command(&a, &commands[2]), app.execute_gate_command(&b, &commands[3]));
    for result in [one, two, three, four] { result.expect("same-case concurrent command failed"); }
    let concurrent_gate = app.read_verified_gate(&a, case_id).await.expect("concurrent gate read failed");
    assert_eq!(concurrent_gate.affirmed, kinds.to_vec());
    assert!(concurrent_gate.gate_affirmed_at.is_some());
    assert!(concurrent_gate.gate_affirmed_by.is_some());
    let latest: (DateTime<Utc>, Uuid) = sqlx::query_as("SELECT affirmed_at,affirmed_by FROM aso.gate_affirmations
        WHERE case_id=$1 ORDER BY affirmed_at DESC,kind DESC LIMIT 1")
        .bind(case_id).fetch_one(&observer).await.expect("concurrent summary verification failed");
    assert_eq!(concurrent_gate.gate_affirmed_at, Some(latest.0));
    assert_eq!(concurrent_gate.gate_affirmed_by, Some(latest.1));
    mark("same_case_concurrency_preserves_complete_derived_summary");
    observer.close().await;
}

//! Concrete identity and membership adapters for the session feature.

use aso_host::{
    ports::SystemClock,
    session::{
        AuthenticatedIdentity, IdentityProvider, Membership, MembershipRepository, Principal,
        SessionCredential, SessionError, SessionPort, SessionService, UnavailableSessions,
    },
};
use async_trait::async_trait;
use chrono::{DateTime, Utc};
use reqwest::{
    Client, Url,
    header::{AUTHORIZATION, COOKIE, HeaderValue},
    redirect,
};
use serde::Deserialize;
use sqlx::{PgPool, postgres::PgPoolOptions};
use std::{sync::Arc, time::Duration};
use uuid::Uuid;

pub struct KratosIdentityProvider {
    client: Client,
    whoami: Url,
}

impl KratosIdentityProvider {
    pub fn new(base: &str, allow_insecure: bool) -> Result<Self, SessionError> {
        let mut url = Url::parse(base).map_err(|_| SessionError::Unavailable)?;
        if !url.username().is_empty()
            || url.password().is_some()
            || url.query().is_some()
            || url.fragment().is_some()
            || !(url.scheme() == "https" || (allow_insecure && url.scheme() == "http"))
        {
            return Err(SessionError::Unavailable);
        }
        url.set_path(&format!(
            "{}/sessions/whoami",
            url.path().trim_end_matches('/')
        ));
        let client = Client::builder()
            .redirect(redirect::Policy::none())
            .timeout(Duration::from_secs(5))
            .no_proxy()
            .build()
            .map_err(|_| SessionError::Unavailable)?;
        Ok(Self {
            client,
            whoami: url,
        })
    }
}

#[derive(Deserialize)]
struct KratosSession {
    id: Uuid,
    active: bool,
    expires_at: DateTime<Utc>,
    identity: KratosIdentity,
}

#[derive(Deserialize)]
struct KratosIdentity {
    id: Uuid,
}

#[async_trait]
impl IdentityProvider for KratosIdentityProvider {
    async fn authenticate(
        &self,
        credential: &SessionCredential,
    ) -> Result<AuthenticatedIdentity, SessionError> {
        let (name, value) = match credential {
            SessionCredential::Cookie(cookie) => (COOKIE, cookie.clone()),
            SessionCredential::NativeToken(token) => (AUTHORIZATION, format!("Bearer {token}")),
        };
        let mut value = HeaderValue::from_str(&value).map_err(|_| SessionError::Unauthenticated)?;
        value.set_sensitive(true);
        let mut response = self
            .client
            .get(self.whoami.clone())
            .header("accept", "application/json")
            .header(name, value)
            .send()
            .await
            .map_err(|_| SessionError::Unavailable)?;
        match response.status().as_u16() {
            200 => {}
            401 => return Err(SessionError::Unauthenticated),
            403 => return Err(SessionError::ReauthenticationRequired),
            _ => return Err(SessionError::Unavailable),
        }
        // Identity traits are untrusted and may be large; keep provider output
        // bounded and deserialize only the authoritative session fields.
        const MAX_SESSION_BYTES: usize = 64 * 1024;
        let mut bytes = Vec::new();
        while let Some(chunk) = response
            .chunk()
            .await
            .map_err(|_| SessionError::Unavailable)?
        {
            if chunk.len() > MAX_SESSION_BYTES - bytes.len() {
                return Err(SessionError::Unavailable);
            }
            bytes.extend_from_slice(&chunk);
        }
        let session: KratosSession =
            serde_json::from_slice(&bytes).map_err(|_| SessionError::Unavailable)?;
        if !session.active || session.expires_at <= Utc::now() {
            return Err(SessionError::Unauthenticated);
        }
        Ok(AuthenticatedIdentity {
            identity_id: session.identity.id,
            session_id: session.id,
            // Kratos authenticates application users. Delegated agents require
            // a separate trusted identity provider and never inherit this value.
            principal: Principal::User,
            expires_at: session.expires_at,
        })
    }
}

pub struct PgMembershipRepository {
    pool: PgPool,
}

impl PgMembershipRepository {
    pub async fn connect(database_url: &str) -> Result<Self, SessionError> {
        let pool = PgPoolOptions::new()
            .max_connections(5)
            .acquire_timeout(Duration::from_secs(5))
            .connect(database_url)
            .await
            .map_err(|_| SessionError::Unavailable)?;
        let repository = Self { pool };
        // Reject owner/superuser service credentials even if SET ROLE could
        // disguise them. Provision a dedicated login member of the read role.
        let allowed: bool = sqlx::query_scalar(ROLE_CHECK)
            .fetch_one(&repository.pool)
            .await
            .map_err(|_| SessionError::Unavailable)?;
        if !allowed {
            return Err(SessionError::Unavailable);
        }
        Ok(repository)
    }

    /// Scope belongs to this transaction only. SQLx queues rollback on Drop for
    /// errors/cancellation; PostgreSQL restores LOCAL settings at either exit.
    async fn begin_scoped(
        &self,
        identity: &AuthenticatedIdentity,
    ) -> Result<sqlx::Transaction<'static, sqlx::Postgres>, SessionError> {
        let mut tx = self
            .pool
            .begin()
            .await
            .map_err(|_| SessionError::Unavailable)?;
        sqlx::query("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
            .execute(&mut *tx)
            .await
            .map_err(|_| SessionError::Unavailable)?;
        let allowed: bool = sqlx::query_scalar(ROLE_CHECK)
            .fetch_one(&mut *tx)
            .await
            .map_err(|_| SessionError::Unavailable)?;
        if !allowed {
            return Err(SessionError::Unavailable);
        }
        sqlx::query("SET LOCAL ROLE aso_session_reader")
            .execute(&mut *tx)
            .await
            .map_err(|_| SessionError::Unavailable)?;
        sqlx::query("SET LOCAL search_path = pg_catalog, aso")
            .execute(&mut *tx)
            .await
            .map_err(|_| SessionError::Unavailable)?;
        sqlx::query("SELECT set_config('aso.kratos_identity_id', $1, true)")
            .bind(identity.identity_id.to_string())
            .execute(&mut *tx)
            .await
            .map_err(|_| SessionError::Unavailable)?;
        sqlx::query("SET LOCAL statement_timeout = '5s'")
            .execute(&mut *tx)
            .await
            .map_err(|_| SessionError::Unavailable)?;
        Ok(tx)
    }

}

const ROLE_CHECK: &str = "
    SELECT pg_has_role(session_user, 'aso_session_reader', 'USAGE')
       AND NOT EXISTS (
         SELECT 1 FROM pg_roles r
         WHERE r.rolname IN (session_user, 'aso_session_reader') AND (
           r.rolsuper OR r.rolbypassrls OR r.rolcreaterole OR r.rolcreatedb OR r.rolreplication
           OR (r.rolname = 'aso_session_reader' AND r.rolcanlogin)
           OR has_schema_privilege(r.oid, 'aso', 'CREATE')
           OR has_database_privilege(r.oid, current_database(), 'CREATE')
           OR EXISTS (SELECT 1 FROM pg_namespace n WHERE n.nspname = 'aso'
                       AND pg_has_role(r.oid, n.nspowner, 'USAGE'))
           OR EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
                       WHERE n.nspname = 'aso' AND (
                         pg_has_role(r.oid, c.relowner, 'USAGE') OR
                         (c.relkind IN ('r', 'p', 'v', 'm', 'f') AND (
                           has_table_privilege(r.oid, c.oid,
                             'INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN') OR
                           has_any_column_privilege(r.oid, c.oid, 'INSERT, UPDATE, REFERENCES')))))
           OR EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                       WHERE n.nspname = 'aso' AND pg_has_role(r.oid, p.proowner, 'USAGE'))
         ))";

#[async_trait]
impl MembershipRepository for PgMembershipRepository {
    async fn resolve(
        &self,
        identity: &AuthenticatedIdentity,
        practice: Option<Uuid>,
    ) -> Result<Membership, SessionError> {
        let mut tx = self.begin_scoped(identity).await?;
        let row: Option<(Uuid, Uuid, String, Vec<String>, String)> = sqlx::query_as("
            SELECT u.id, COALESCE($2, u.practice_id),
                   COALESCE(u.display_name, u.full_name),
                   ARRAY(SELECT c.capability_key FROM aso.user_capabilities c
                         WHERE c.user_id = u.id AND c.practice_id = COALESCE($2, u.practice_id)
                         ORDER BY c.capability_key),
                   r.incarnation::text || ':' || r.revision::text
            FROM aso.users u CROSS JOIN aso.authorization_revision r
            WHERE u.id = aso.current_app_user_id() AND u.kratos_identity_id = $1
              AND u.status = 'active' AND r.singleton
              AND EXISTS (SELECT 1 FROM aso.user_roles ur
                          WHERE ur.user_id = u.id AND ur.practice_id = COALESCE($2, u.practice_id))")
            .bind(identity.identity_id).bind(practice).fetch_optional(&mut *tx)
            .await.map_err(|_| SessionError::Unavailable)?;
        tx.commit().await.map_err(|_| SessionError::Unavailable)?;
        let (user_id, practice_id, display_name, capabilities, authorization_revision) =
            row.ok_or(SessionError::PracticeDenied)?;
        Ok(Membership {
            user_id,
            practice_id,
            display_name,
            capabilities,
            authorization_revision,
        })
    }
}

pub async fn configured_sessions(
    database_url: Option<String>,
    kratos_url: Option<String>,
    allow_insecure: bool,
) -> Result<Arc<dyn SessionPort>, SessionError> {
    match (database_url, kratos_url) {
        (None, None) => Ok(Arc::new(UnavailableSessions)),
        (Some(database), Some(kratos)) => Ok(Arc::new(SessionService {
            identities: Arc::new(KratosIdentityProvider::new(&kratos, allow_insecure)?),
            memberships: Arc::new(PgMembershipRepository::connect(&database).await?),
            clock: Arc::new(SystemClock),
        })),
        _ => Err(SessionError::Unavailable),
    }
}

#[cfg(test)]
mod transaction_tests;

#[cfg(test)]
mod tests {
    use super::*;
    use axum::{Router, http::StatusCode, routing::get};

    #[tokio::test]
    async fn session_provider_refuses_invalid_or_unavailable_authority() {
        let valid = serde_json::json!({
            "id": Uuid::new_v4(), "active": true,
            "expires_at": (Utc::now() + chrono::Duration::minutes(5)).to_rfc3339(),
            "identity": { "id": Uuid::new_v4(), "traits": { "role": "surgeon" } },
        });
        let mut inactive = valid.clone();
        inactive["active"] = false.into();
        let mut missing_active = valid.clone();
        missing_active.as_object_mut().unwrap().remove("active");
        let mut expired = valid.clone();
        expired["expires_at"] = "2000-01-01T00:00:00Z".into();
        let scenarios = [
            (200, inactive.to_string(), SessionError::Unauthenticated),
            (200, missing_active.to_string(), SessionError::Unavailable),
            (200, expired.to_string(), SessionError::Unauthenticated),
            (200, "invalid JSON".into(), SessionError::Unavailable),
            (200, "x".repeat(65 * 1024), SessionError::Unavailable),
            (401, "{}".into(), SessionError::Unauthenticated),
            (403, "{}".into(), SessionError::ReauthenticationRequired),
            (302, "{}".into(), SessionError::Unavailable),
            (500, "{}".into(), SessionError::Unavailable),
        ];
        for (status, body, expected) in scenarios {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
            let base = format!("http://{}", listener.local_addr().unwrap());
            let app = Router::new().route(
                "/sessions/whoami",
                get(move || {
                    let body = body.clone();
                    async move { (StatusCode::from_u16(status).unwrap(), body) }
                }),
            );
            let server = tokio::spawn(async move {
                axum::serve(listener, app).await.unwrap();
            });
            let provider = KratosIdentityProvider::new(&base, true).unwrap();
            let result = provider
                .authenticate(&SessionCredential::NativeToken("synthetic-test".into()))
                .await;
            server.abort();
            assert!(matches!(result, Err(error) if error == expected));
        }
    }

    #[tokio::test]
    async fn session_provider_connection_failure_is_unavailable() {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let base = format!("http://{}", listener.local_addr().unwrap());
        drop(listener);
        let provider = KratosIdentityProvider::new(&base, true).unwrap();
        let result = provider
            .authenticate(&SessionCredential::NativeToken("synthetic-test".into()))
            .await;
        assert!(matches!(result, Err(SessionError::Unavailable)));
    }

    #[test]
    fn session_provider_requires_explicit_plaintext_development_opt_in() {
        assert!(KratosIdentityProvider::new("http://localhost:4433", false).is_err());
        assert!(
            KratosIdentityProvider::new("https://localhost:4433?token=synthetic", false).is_err()
        );
        assert!(
            KratosIdentityProvider::new("https://user:synthetic@localhost:4433", false).is_err()
        );
        assert!(KratosIdentityProvider::new("https://localhost:4433", false).is_ok());
    }
}

//! Run only through scripts/test-session-context.py, against its disposable DB.

use super::*;

type ConnectionState = (i32, bool, String, String, String, String, String);

async fn state(pool: &PgPool) -> ConnectionState {
    sqlx::query_as("SELECT pg_backend_pid(), current_user = session_user,
        COALESCE(current_setting('aso.kratos_identity_id', true), ''),
        current_setting('search_path'), current_setting('statement_timeout'),
        current_setting('transaction_read_only'), current_setting('transaction_isolation')")
        .fetch_one(pool).await.expect("read connection state")
}

async fn assert_clean(pool: &PgPool, baseline: &ConnectionState, label: &str) {
    let actual = tokio::time::timeout(Duration::from_secs(15), state(pool))
        .await.expect("connection must become reusable after transaction exit");
    // Includes PID: a replacement connection cannot disguise leaked settings.
    assert_eq!(&actual, baseline, "connection context leaked after {label}");
    println!("context check passed: {label}");
}

#[tokio::test]
#[ignore = "requires isolated fixture: RUSTUP_TOOLCHAIN=1.97.1 python3 scripts/test-session-context.py"]
async fn session_transaction_context_lifecycle() {
    let url = std::env::var("ASO_TEST_DATABASE_URL").expect("disposable DB required");
    let identity = AuthenticatedIdentity {
        identity_id: std::env::var("ASO_TEST_IDENTITY_ID").unwrap().parse().unwrap(),
        session_id: Uuid::new_v4(),
        principal: aso_host::session::Principal::User,
        expires_at: Utc::now() + chrono::Duration::minutes(5),
    };
    let practice: Uuid = std::env::var("ASO_TEST_PRACTICE_ID").unwrap().parse().unwrap();
    let pool = PgPoolOptions::new().max_connections(1)
        .acquire_timeout(Duration::from_secs(15)).connect(&url).await
        .expect("connect restricted disposable login");
    let repo = Arc::new(PgMembershipRepository { pool });
    let baseline = state(&repo.pool).await;
    assert!(baseline.1 && baseline.2.is_empty(), "fixture must start unscoped");

    let mut tx = repo.begin_scoped(&identity).await.unwrap();
    let scoped: (bool, String, Uuid, bool, String, String) = sqlx::query_as(
        "SELECT current_user = 'aso_session_reader',
         current_setting('aso.kratos_identity_id'), aso.current_app_user_id(),
         current_setting('transaction_read_only') = 'on',
         current_setting('transaction_isolation'), current_setting('statement_timeout')")
        .fetch_one(&mut *tx).await.unwrap();
    assert!(scoped.0 && scoped.3);
    assert_eq!(scoped.1, identity.identity_id.to_string());
    assert_eq!(scoped.2, std::env::var("ASO_TEST_USER_ID").unwrap().parse::<Uuid>().unwrap());
    assert_eq!(scoped.4, "repeatable read");
    assert_eq!(scoped.5, "5s");
    tx.commit().await.unwrap();
    assert_clean(&repo.pool, &baseline, "explicit_commit").await;

    assert_eq!(repo.resolve(&identity, Some(practice)).await.unwrap().practice_id, practice);
    assert_clean(&repo.pool, &baseline, "mounted_repository_success").await;
    assert!(matches!(repo.resolve(&identity, Some(Uuid::new_v4())).await,
        Err(SessionError::PracticeDenied)));
    assert_clean(&repo.pool, &baseline, "mounted_repository_denial").await;

    let mut tx = repo.begin_scoped(&identity).await.unwrap();
    let failure = sqlx::query("SELECT 1/0").execute(&mut *tx).await.unwrap_err();
    assert_eq!(failure.as_database_error().unwrap().code().as_deref(), Some("22012"));
    drop(tx);
    assert_clean(&repo.pool, &baseline, "sql_error_drop_rollback").await;

    let tx = repo.begin_scoped(&identity).await.unwrap();
    tx.rollback().await.unwrap();
    assert_clean(&repo.pool, &baseline, "explicit_rollback").await;

    // Observe a query actually running before cancelling its owning future.
    let observer = PgPoolOptions::new().max_connections(1).connect(&url).await.unwrap();
    let task_repo = Arc::clone(&repo);
    let task = tokio::spawn(async move {
        let mut tx = task_repo.begin_scoped(&identity).await.unwrap();
        sqlx::query("SELECT pg_sleep(30)").execute(&mut *tx).await
    });
    tokio::time::timeout(Duration::from_secs(3), async {
        loop {
            let running: bool = sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM pg_stat_activity
                WHERE pid = $1 AND state = 'active' AND wait_event = 'PgSleep')")
                .bind(baseline.0).fetch_one(&observer).await.unwrap();
            if running { break; }
            tokio::task::yield_now().await;
        }
    }).await.expect("must observe active database query before abort");
    task.abort();
    assert!(task.await.unwrap_err().is_cancelled());
    let mut after_cancel = tokio::time::timeout(Duration::from_secs(15), state(&repo.pool))
        .await.expect("cancelled connection must be cleaned or discarded");
    let replaced = after_cancel.0 != baseline.0;
    if replaced {
        // SQLx 0.8 discards a connection if its on-release ping receives the
        // interrupted query's timeout error. Prove that backend was removed.
        let old_backend_exists: bool = sqlx::query_scalar(
            "SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE pid = $1)")
            .bind(baseline.0).fetch_one(&observer).await.unwrap();
        assert!(!old_backend_exists, "interrupted backend must not survive discard");
    }
    after_cancel.0 = baseline.0;
    assert_eq!(after_cancel, baseline, "next borrower must have no prior context");
    println!("context check passed: in_flight_cancellation_clean_or_discarded (replaced={replaced})");
    observer.close().await;
    repo.pool.close().await;
}

//! Explicit deployment operation. Ordinary server startup never reads migration
//! credentials or runs DDL. The existing ASO schema is a prerequisite.

use sqlx::{migrate::{Migration, MigrationSource, MigrationType, Migrator}, postgres::PgPoolOptions};
use std::{future::Future, pin::Pin};

#[derive(Debug)]
struct ServerMigrations;

impl MigrationSource<'static> for ServerMigrations {
    fn resolve(self) -> Pin<Box<dyn Future<Output = Result<Vec<Migration>, sqlx::error::BoxDynError>> + Send>> {
        Box::pin(async {
            Ok(vec![Migration::new(
                2026090601,
                "durable gate".into(),
                MigrationType::Simple,
                include_str!("../../../migrations/server/2026090601_durable_gate.sql").into(),
                false,
            )])
        })
    }
}

pub async fn run() -> Result<(), Box<dyn std::error::Error>> {
    let url = std::env::var("ASO_MIGRATION_DATABASE_URL")
        .map_err(|_| "ASO_MIGRATION_DATABASE_URL is required for --migrate-server")?;
    let pool = PgPoolOptions::new().max_connections(1).connect(&url).await
        .map_err(|_| "server migration connection failed")?;
    // SQLx takes its migration lock, validates SHA-384 checksums, and commits
    // each migration and its ledger entry in one transaction.
    let result = Migrator::new(ServerMigrations).await?.run(&pool).await;
    pool.close().await;
    match result {
        Ok(()) => { println!("server migrations applied and checksums verified"); Ok(()) }
        Err(sqlx::migrate::MigrateError::VersionMismatch(_)) =>
            Err("server migration checksum mismatch: applied SQL was modified".into()),
        // SQL errors can contain record values. Keep deployment output generic.
        Err(_) => Err("server migration failed; database unchanged for the failed migration".into()),
    }
}

-- RA-02. Applied transactionally by the checksummed server migrator after
-- schema.sql and 25-session-authority.sql, on both fresh and existing stores.
-- gate_commands lane: server-authoritative relational. Privacy: local.
-- Original clinical command results and their audit are never replicated.
-- The trusted host supplies verified, transaction-local session settings.
-- A database credential is not a Kratos verifier: never expose it to clients.

DO $$
DECLARE
  role_name text;
  role_id oid;
BEGIN
  IF EXISTS (SELECT FROM pg_catalog.pg_publication WHERE puballtables)
     OR EXISTS (
       SELECT FROM pg_catalog.pg_publication_namespace pn
       JOIN pg_catalog.pg_namespace n ON n.oid = pn.pnnspid
       WHERE n.nspname = 'aso'
     ) THEN
    RAISE EXCEPTION 'local gate command data requires explicit-table publications';
  END IF;

  FOREACH role_name IN ARRAY ARRAY['aso_gate_owner', 'aso_gate_executor'] LOOP
    SELECT oid INTO role_id FROM pg_catalog.pg_roles WHERE rolname = role_name;
    IF role_id IS NULL THEN
      EXECUTE format('CREATE ROLE %I NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS', role_name);
    ELSE
      IF EXISTS (
        SELECT FROM pg_catalog.pg_roles WHERE oid = role_id
          AND (rolcanlogin OR rolsuper OR rolcreatedb OR rolcreaterole
               OR rolreplication OR rolbypassrls)
      ) OR EXISTS (
        SELECT FROM pg_catalog.pg_auth_members WHERE member = role_id
      ) OR EXISTS (
        SELECT FROM pg_catalog.pg_database WHERE datdba = role_id
      ) OR EXISTS (
        SELECT FROM pg_catalog.pg_namespace WHERE nspowner = role_id
      ) OR EXISTS (
        SELECT FROM pg_catalog.pg_class c
        JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'aso' AND (c.relowner = role_id OR
          (c.relkind IN ('r', 'p', 'v', 'm', 'f') AND
            (pg_catalog.has_table_privilege(role_id, c.oid,
              'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN')
             OR pg_catalog.has_any_column_privilege(role_id, c.oid,
              'SELECT, INSERT, UPDATE, REFERENCES'))))
      ) OR EXISTS (
        SELECT FROM pg_catalog.pg_proc p
        JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'aso' AND p.proowner = role_id
      ) OR pg_catalog.has_schema_privilege(role_id, 'aso', 'CREATE') THEN
        RAISE EXCEPTION '% already exists with privileged access', role_name;
      END IF;
    END IF;
  END LOOP;
  -- Membership in the definer owner would expose its table grants directly.
  IF EXISTS (
    SELECT FROM pg_catalog.pg_auth_members m
    JOIN pg_catalog.pg_roles r ON r.oid = m.roleid
    WHERE r.rolname = 'aso_gate_owner'
  ) THEN
    RAISE EXCEPTION 'aso_gate_owner must have no members';
  END IF;
END;
$$;

CREATE TABLE aso.gate_commands (
  kratos_identity_id uuid NOT NULL,
  practice_id uuid NOT NULL REFERENCES aso.practices(id) ON DELETE RESTRICT,
  command_id uuid NOT NULL,
  actor_id uuid NOT NULL REFERENCES aso.users(id) ON DELETE RESTRICT,
  case_id uuid NOT NULL REFERENCES aso.cases(id) ON DELETE RESTRICT,
  kind text NOT NULL REFERENCES aso.gate_affirmation_kinds(key),
  action text NOT NULL CHECK (action IN ('affirm', 'remove')),
  result jsonb NOT NULL,
  committed_at timestamptz NOT NULL,
  PRIMARY KEY (kratos_identity_id, practice_id, command_id)
);
COMMENT ON TABLE aso.gate_commands IS
  'Lane: server-authoritative relational. Privacy: local. Immutable clinical command results; excluded from replication.';
ALTER TABLE aso.gate_commands ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON aso.gate_commands FROM PUBLIC;

GRANT USAGE ON SCHEMA aso TO aso_gate_owner, aso_gate_executor;
GRANT SELECT (id, kratos_identity_id, practice_id, status, full_name)
  ON aso.users TO aso_gate_owner;
GRANT SELECT ON aso.user_roles, aso.user_capabilities,
  aso.gate_affirmation_kinds, aso.gate_affirmations, aso.gate_commands
  TO aso_gate_owner;
GRANT SELECT (id, practice_id, gate_affirmed_at, gate_affirmed_by),
  UPDATE (gate_affirmed_at, gate_affirmed_by) ON aso.cases TO aso_gate_owner;
GRANT INSERT (case_id, kind, affirmed_by, affirmed_at),
  UPDATE (affirmed_by, affirmed_at), DELETE ON aso.gate_affirmations
  TO aso_gate_owner;
GRANT INSERT ON aso.gate_commands TO aso_gate_owner;
GRANT INSERT (practice_id, occurred_at, actor_id, actor_kratos_id, actor_label,
  actor_role, action, outcome, entity_table, entity_id, case_id, summary, data)
  ON aso.audit_events TO aso_gate_owner;
DO $$
BEGIN
  EXECUTE format('GRANT USAGE ON SEQUENCE %s TO aso_gate_owner',
    pg_catalog.pg_get_serial_sequence('aso.audit_events', 'id'));
END;
$$;

-- The owner can see case scope to distinguish missing from foreign cases;
-- public functions check that scope before returning any clinical data.
CREATE POLICY cases_gate_owner ON aso.cases TO aso_gate_owner
  USING (true) WITH CHECK (true);
CREATE POLICY gate_commands_owner ON aso.gate_commands TO aso_gate_owner
  USING (true) WITH CHECK (true);
CREATE POLICY audit_gate_insert ON aso.audit_events FOR INSERT TO aso_gate_owner
  WITH CHECK (
    actor_id = NULLIF(current_setting('aso.actor_id', true), '')::uuid
    AND actor_kratos_id = NULLIF(current_setting('aso.kratos_identity_id', true), '')::uuid
    AND practice_id = NULLIF(current_setting('aso.practice_id', true), '')::uuid
    AND current_setting('aso.principal', true) = 'user'
  );

CREATE FUNCTION aso.gate_actor_context()
RETURNS TABLE (actor_id uuid, identity_id uuid, practice_id uuid, actor_label text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, aso, pg_temp
AS $$
DECLARE
  context_actor uuid;
  context_identity uuid;
  context_practice uuid;
  context_expiry timestamptz;
BEGIN
  BEGIN
    context_actor := NULLIF(current_setting('aso.actor_id', true), '')::uuid;
    context_identity := NULLIF(current_setting('aso.kratos_identity_id', true), '')::uuid;
    context_practice := NULLIF(current_setting('aso.practice_id', true), '')::uuid;
    context_expiry := NULLIF(current_setting('aso.session_expires_at', true), '')::timestamptz;
  EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN
    RAISE EXCEPTION 'invalid gate session context' USING ERRCODE = '42501';
  END;
  IF current_setting('aso.principal', true) IS DISTINCT FROM 'user'
     OR context_actor IS NULL OR context_identity IS NULL OR context_practice IS NULL
     OR context_expiry IS NULL OR NOT isfinite(context_expiry)
     OR context_expiry <= clock_timestamp() THEN
    RAISE EXCEPTION 'active human session required' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT u.id, u.kratos_identity_id, context_practice, u.full_name
    FROM aso.users u
    WHERE u.id = context_actor AND u.kratos_identity_id = context_identity
      AND u.status = 'active'
      AND EXISTS (SELECT FROM aso.user_roles ur
        WHERE ur.user_id = u.id AND ur.practice_id = context_practice);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate session identity or membership denied' USING ERRCODE = '42501';
  END IF;
END;
$$;

CREATE FUNCTION aso.require_gate_case(target_case uuid, clinical boolean)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, aso, pg_temp
AS $$
DECLARE
  actor record;
  case_practice uuid;
BEGIN
  SELECT * INTO STRICT actor FROM aso.gate_actor_context();
  SELECT c.practice_id INTO case_practice FROM aso.cases c WHERE c.id = target_case;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate case not found' USING ERRCODE = 'P0002';
  END IF;
  IF case_practice <> actor.practice_id OR (clinical AND NOT EXISTS (
    SELECT FROM aso.user_capabilities uc
    WHERE uc.user_id = actor.actor_id AND uc.practice_id = actor.practice_id
      AND uc.capability_key = 'affirm_gate' AND uc.is_clinical
  )) THEN
    RAISE EXCEPTION 'gate case authority denied' USING ERRCODE = '42501';
  END IF;
END;
$$;

CREATE FUNCTION aso.read_gate(target_case uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, aso, pg_temp
AS $$
DECLARE
  result jsonb;
BEGIN
  PERFORM aso.require_gate_case(target_case, false);
  SELECT jsonb_build_object(
    'caseId', c.id,
    'affirmed', COALESCE((
      SELECT jsonb_agg(a.kind ORDER BY k.ordinal)
      FROM aso.gate_affirmations a JOIN aso.gate_affirmation_kinds k ON k.key = a.kind
      WHERE a.case_id = c.id
    ), '[]'::jsonb),
    'gateAffirmedAt', c.gate_affirmed_at,
    'gateAffirmedBy', c.gate_affirmed_by)
    INTO result FROM aso.cases c WHERE c.id = target_case;
  RETURN result;
END;
$$;

CREATE FUNCTION aso.may_affirm_gate(target_case uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, aso, pg_temp
AS $$
BEGIN
  PERFORM aso.require_gate_case(target_case, true);
  RETURN true;
EXCEPTION WHEN insufficient_privilege OR no_data_found THEN
  RETURN false;
END;
$$;

CREATE FUNCTION aso.lookup_gate_command(target_command uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, aso, pg_temp
AS $$
DECLARE
  actor record;
  original jsonb;
BEGIN
  SELECT * INTO STRICT actor FROM aso.gate_actor_context();
  SELECT g.result INTO original FROM aso.gate_commands g
    WHERE g.kratos_identity_id = actor.identity_id
      AND g.practice_id = actor.practice_id AND g.command_id = target_command;
  RETURN original;
END;
$$;

-- This trigger is an independent database boundary. It checks DELETE too,
-- and never infers authority from the affirmer stored on an existing row.
CREATE OR REPLACE FUNCTION aso.enforce_gate_authority()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, aso, pg_temp
AS $$
DECLARE
  actor record;
  target_case uuid;
BEGIN
  IF current_user <> 'aso_gate_owner' THEN
    RAISE EXCEPTION 'gate writes require the command function' USING ERRCODE = '42501';
  END IF;
  target_case := CASE WHEN TG_OP = 'DELETE' THEN OLD.case_id ELSE NEW.case_id END;
  SELECT * INTO STRICT actor FROM aso.gate_actor_context();
  PERFORM aso.require_gate_case(target_case, true);
  PERFORM c.id FROM aso.cases c WHERE c.id = target_case FOR UPDATE;
  IF TG_OP <> 'DELETE' AND NEW.affirmed_by <> actor.actor_id THEN
    RAISE EXCEPTION 'gate affirmer must be the verified actor' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.case_id <> OLD.case_id OR NEW.kind <> OLD.kind) THEN
    RAISE EXCEPTION 'gate affirmation identity is immutable' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;
CREATE OR REPLACE TRIGGER gate_affirmations_authority
  BEFORE INSERT OR UPDATE OR DELETE ON aso.gate_affirmations
  FOR EACH ROW EXECUTE FUNCTION aso.enforce_gate_authority();

CREATE OR REPLACE FUNCTION aso.refresh_case_gate()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, aso, pg_temp
AS $$
DECLARE
  target_case uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.case_id ELSE NEW.case_id END;
  last_by uuid;
  last_at timestamptz;
BEGIN
  IF current_user <> 'aso_gate_owner' THEN
    RAISE EXCEPTION 'gate summary requires the command function' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT FROM aso.gate_affirmation_kinds k
    WHERE NOT EXISTS (SELECT FROM aso.gate_affirmations a
      WHERE a.case_id = target_case AND a.kind = k.key)
  ) THEN
    SELECT a.affirmed_at, a.affirmed_by INTO last_at, last_by
      FROM aso.gate_affirmations a WHERE a.case_id = target_case
      ORDER BY a.affirmed_at DESC, a.kind DESC LIMIT 1;
  END IF;
  UPDATE aso.cases SET gate_affirmed_at = last_at, gate_affirmed_by = last_by
    WHERE id = target_case;
  RETURN NULL;
END;
$$;

-- Existing installations allowed direct summary writes. Reconcile those
-- rows before protecting the derived columns, retaining valid complete gates
-- and leaving already-correct pairs (and their updated_at values) untouched.
WITH expected_gate AS (
  SELECT c.id, latest.affirmed_at, latest.affirmed_by
  FROM aso.cases c
  LEFT JOIN LATERAL (
    SELECT a.affirmed_at, a.affirmed_by
    FROM aso.gate_affirmations a
    WHERE a.case_id = c.id AND NOT EXISTS (
      SELECT FROM aso.gate_affirmation_kinds k
      WHERE NOT EXISTS (
        SELECT FROM aso.gate_affirmations required
        WHERE required.case_id = c.id AND required.kind = k.key
      )
    )
    ORDER BY a.affirmed_at DESC, a.kind DESC
    LIMIT 1
  ) latest ON true
)
UPDATE aso.cases c
  SET gate_affirmed_at = expected.affirmed_at,
      gate_affirmed_by = expected.affirmed_by
  FROM expected_gate expected
  WHERE c.id = expected.id
    AND (c.gate_affirmed_at, c.gate_affirmed_by)
      IS DISTINCT FROM (expected.affirmed_at, expected.affirmed_by);

CREATE FUNCTION aso.guard_case_gate_summary()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, aso, pg_temp
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.gate_affirmed_at IS NOT NULL OR NEW.gate_affirmed_by IS NOT NULL THEN
      RAISE EXCEPTION 'gate summary is derived from affirmations' USING ERRCODE = '42501';
    END IF;
  ELSIF (NEW.gate_affirmed_at IS DISTINCT FROM OLD.gate_affirmed_at
      OR NEW.gate_affirmed_by IS DISTINCT FROM OLD.gate_affirmed_by)
      AND (current_user <> 'aso_gate_owner' OR pg_trigger_depth() <> 2) THEN
    RAISE EXCEPTION 'gate summary is derived from affirmations' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER cases_gate_summary_guard
  BEFORE INSERT OR UPDATE OF gate_affirmed_at, gate_affirmed_by ON aso.cases
  FOR EACH ROW EXECUTE FUNCTION aso.guard_case_gate_summary();

CREATE FUNCTION aso.gate_commands_immutable()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, aso, pg_temp
AS $$
BEGIN
  RAISE EXCEPTION 'gate command results are immutable' USING ERRCODE = '42501';
END;
$$;
CREATE TRIGGER gate_commands_immutable
  BEFORE UPDATE OR DELETE OR TRUNCATE ON aso.gate_commands
  FOR EACH STATEMENT EXECUTE FUNCTION aso.gate_commands_immutable();

CREATE FUNCTION aso.apply_gate_command(
  target_command uuid, target_case uuid, target_kind text, target_action text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, aso, pg_temp
AS $$
DECLARE
  actor record;
  original aso.gate_commands%ROWTYPE;
  result jsonb;
  committed_at timestamptz;
BEGIN
  SELECT * INTO STRICT actor FROM aso.gate_actor_context();
  IF target_command IS NULL THEN
    RAISE EXCEPTION 'invalid gate command payload' USING ERRCODE = '22023';
  END IF;

  -- Compare an identity/practice-scoped command before target-case authority.
  -- The caller already owns this opaque command ID; doing so makes conflicts
  -- explicit without exposing another identity or practice's command ledger.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    actor.identity_id::text || ':' || actor.practice_id::text || ':' || target_command::text, 0));
  SELECT * INTO original FROM aso.gate_commands g
    WHERE g.kratos_identity_id = actor.identity_id
      AND g.practice_id = actor.practice_id AND g.command_id = target_command;
  IF FOUND THEN
    IF original.case_id IS DISTINCT FROM target_case
       OR original.kind IS DISTINCT FROM target_kind
       OR original.action IS DISTINCT FROM target_action
       OR original.actor_id IS DISTINCT FROM actor.actor_id THEN
      RAISE EXCEPTION 'gate command ID has a different payload' USING ERRCODE = '23505';
    END IF;
  END IF;

  IF target_case IS NULL OR target_kind IS NULL OR target_action IS NULL
     OR target_action NOT IN ('affirm', 'remove') OR NOT EXISTS (
       SELECT FROM aso.gate_affirmation_kinds WHERE key = target_kind
     ) THEN
    RAISE EXCEPTION 'invalid gate command payload' USING ERRCODE = '22023';
  END IF;
  PERFORM aso.require_gate_case(target_case, true);
  PERFORM c.id FROM aso.cases c WHERE c.id = target_case FOR UPDATE;
  -- Locks can wait beyond session expiry or an authority change.
  PERFORM aso.require_gate_case(target_case, true);
  IF original.command_id IS NOT NULL THEN
    RETURN original.result;
  END IF;

  committed_at := clock_timestamp();
  IF target_action = 'affirm' THEN
    INSERT INTO aso.gate_affirmations (case_id, kind, affirmed_by, affirmed_at)
      VALUES (target_case, target_kind, actor.actor_id, committed_at)
      ON CONFLICT (case_id, kind) DO UPDATE
        SET affirmed_by = EXCLUDED.affirmed_by, affirmed_at = EXCLUDED.affirmed_at;
  ELSE
    DELETE FROM aso.gate_affirmations WHERE case_id = target_case AND kind = target_kind;
  END IF;

  result := jsonb_build_object(
    'commandId', target_command, 'caseId', target_case,
    'kind', target_kind, 'action', target_action,
    'gate', aso.read_gate(target_case), 'committedAt', committed_at);
  INSERT INTO aso.audit_events (
    practice_id, occurred_at, actor_id, actor_kratos_id, actor_label, actor_role,
    action, outcome, entity_table, entity_id, case_id, summary, data)
  VALUES (
    actor.practice_id, committed_at, actor.actor_id, actor.identity_id,
    actor.actor_label, 'clinical:affirm_gate', 'gate.' || target_action, 'success',
    'gate_affirmations', target_case, target_case,
    'Surgeon gate ' || target_kind || ': ' || target_action,
    jsonb_build_object('commandId', target_command, 'kind', target_kind));
  INSERT INTO aso.gate_commands (
    kratos_identity_id, practice_id, command_id, actor_id, case_id,
    kind, action, result, committed_at)
  VALUES (actor.identity_id, actor.practice_id, target_command, actor.actor_id,
    target_case, target_kind, target_action, result, committed_at);
  RETURN result;
END;
$$;

-- Transfer only the bounded functions. No runtime role may become the owner.
-- CREATE is temporary for ownership transfer and revoked in this transaction.
GRANT CREATE ON SCHEMA aso TO aso_gate_owner;
DO $$
DECLARE
  signature text;
BEGIN
  FOREACH signature IN ARRAY ARRAY[
    'aso.gate_actor_context()', 'aso.require_gate_case(uuid,boolean)',
    'aso.read_gate(uuid)', 'aso.may_affirm_gate(uuid)',
    'aso.lookup_gate_command(uuid)', 'aso.enforce_gate_authority()',
    'aso.refresh_case_gate()', 'aso.guard_case_gate_summary()',
    'aso.gate_commands_immutable()', 'aso.apply_gate_command(uuid,uuid,text,text)'
  ] LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', signature);
    EXECUTE format('ALTER FUNCTION %s OWNER TO aso_gate_owner', signature);
  END LOOP;
END;
$$;
REVOKE CREATE ON SCHEMA aso FROM aso_gate_owner;
GRANT EXECUTE ON FUNCTION aso.read_gate(uuid), aso.may_affirm_gate(uuid),
  aso.lookup_gate_command(uuid), aso.apply_gate_command(uuid,uuid,text,text)
  TO aso_gate_executor;

-- Provision a separate non-owner LOGIN through deployment secrets with only
-- aso_gate_executor membership. Transactions SET LOCAL ROLE aso_gate_executor.
-- aso_session_reader is deliberately unchanged.

import { act, cleanup, renderHook, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { ApiError, httpClient } from '../../../shared/api/http-client';
import type { GateCommandResult, GateSnapshot } from '../model/gate-state';
import { useSurgeonGate } from './use-surgeon-gate';

vi.mock('../../../shared/api/http-client', async (importOriginal) => ({
  ...await importOriginal<typeof import('../../../shared/api/http-client')>(),
  httpClient: { get: vi.fn(), post: vi.fn() },
}));

const caseId = '11111111-1111-4111-8111-111111111111';
const practiceId = '22222222-2222-4222-8222-222222222222';
const snapshot: GateSnapshot = {
  caseId,
  affirmed: ['policy', 'section', 'pathway', 'plan'],
  gateAffirmedAt: '2026-09-06T12:00:00Z',
  gateAffirmedBy: '33333333-3333-4333-8333-333333333333',
};

function receipt(commandId: string, action: 'affirm' | 'remove' = 'affirm'): GateCommandResult {
  return {
    commandId,
    caseId,
    kind: 'plan',
    action,
    gate: action === 'affirm' ? snapshot : {
      ...snapshot,
      affirmed: ['policy', 'section', 'pathway'],
      gateAffirmedAt: null,
      gateAffirmedBy: null,
    },
    committedAt: '2026-09-06T12:00:00Z',
  };
}

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (reason: Error) => void;
  const promise = new Promise<T>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

beforeEach(() => {
  vi.resetAllMocks();
  vi.mocked(httpClient.get).mockResolvedValue(snapshot);
});
afterEach(cleanup);

describe('the surgeon gate uses authenticated command DTOs', () => {
  it('adapts snapshots and mutation receipts while sending only kind and a fresh command ID', async () => {
    const { result } = renderHook(() => useSurgeonGate(caseId, { practiceId }));
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(httpClient.get).toHaveBeenCalledWith(`/api/cases/${caseId}/gate?practiceId=${practiceId}`);
    expect(result.current.state).toEqual({ affirmed: true, outstanding: [] });

    vi.mocked(httpClient.post).mockImplementation(async (_path, body) =>
      receipt((body as { commandId: string }).commandId, 'remove'));
    await act(async () => result.current.remove('plan'));
    const removalId = result.current.lastCommandId;
    expect(removalId).toMatch(/^[0-9a-f-]{36}$/);
    expect(httpClient.post).toHaveBeenLastCalledWith(
      `/api/cases/${caseId}/gate/remove?practiceId=${practiceId}`,
      { commandId: removalId, kind: 'plan' },
    );
    expect(result.current.state).toEqual({ affirmed: false, outstanding: ['plan'] });

    vi.mocked(httpClient.post).mockImplementation(async (_path, body) =>
      receipt((body as { commandId: string }).commandId));
    await act(async () => result.current.affirm('plan'));
    expect(result.current.lastCommandId).not.toBe(removalId);
    expect(httpClient.post).toHaveBeenLastCalledWith(
      `/api/cases/${caseId}/gate/affirm?practiceId=${practiceId}`,
      { commandId: result.current.lastCommandId, kind: 'plan' },
    );
    expect(result.current.state).toEqual({ affirmed: true, outstanding: [] });
    expect(httpClient.post).toHaveBeenCalledTimes(2);
  });

  it('retains an uncertain command for explicit lookup without retrying the write', async () => {
    const { result } = renderHook(() => useSurgeonGate(caseId));
    await waitFor(() => expect(result.current.loading).toBe(false));
    vi.mocked(httpClient.post).mockRejectedValue(new Error('Response lost'));

    await act(async () => {
      await expect(result.current.remove('plan')).rejects.toThrow('Response lost');
    });
    const commandId = result.current.lastCommandId!;
    expect(commandId).toMatch(/^[0-9a-f-]{36}$/);
    expect(httpClient.post).toHaveBeenCalledTimes(1);
    expect(result.current.state).toEqual({ affirmed: true, outstanding: [] });

    const committed = receipt(commandId, 'remove');
    const current: GateSnapshot = { ...committed.gate, affirmed: ['policy', 'pathway'] };
    vi.mocked(httpClient.get).mockResolvedValueOnce(committed).mockResolvedValueOnce(current);
    await act(async () => {
      await expect(result.current.lookupCommand(commandId)).resolves.toEqual(committed);
    });
    expect(httpClient.get).toHaveBeenNthCalledWith(2,
      `/api/cases/${caseId}/gate/commands/${commandId}`,
    );
    expect(httpClient.get).toHaveBeenLastCalledWith(`/api/cases/${caseId}/gate`);
    expect(result.current.state).toEqual({ affirmed: false, outstanding: ['section', 'plan'] });
    expect(httpClient.post).toHaveBeenCalledTimes(1);
    expect(result.current.lastCommandId).toBe(commandId);

    vi.mocked(httpClient.get).mockRejectedValue(new ApiError(404, 'Command not found'));
    await expect(result.current.lookupCommand(commandId)).rejects.toMatchObject({ status: 404 });
    expect(httpClient.post).toHaveBeenCalledTimes(1);
  });

  it('surfaces a refusal without converting the committed gate to an unaffirmed state', async () => {
    const { result } = renderHook(() => useSurgeonGate(caseId));
    await waitFor(() => expect(result.current.loading).toBe(false));
    vi.mocked(httpClient.post).mockRejectedValue(new ApiError(403, 'Gate access denied'));
    await act(async () => result.current.remove('plan'));
    expect(result.current.refusal).toBe('Gate access denied');
    expect(result.current.lastCommandId).toBeNull();
    expect(result.current.state).toEqual({ affirmed: true, outstanding: [] });
    expect(httpClient.post).toHaveBeenCalledTimes(1);
  });

  it.each(['case', 'practice'])('clears prior data and command feedback immediately on a %s switch', async (selection) => {
    const { result, rerender } = renderHook(
      ({ selectedCase, selectedPractice }) => useSurgeonGate(selectedCase, { practiceId: selectedPractice }),
      { initialProps: { selectedCase: caseId, selectedPractice: practiceId } },
    );
    await waitFor(() => expect(result.current.loading).toBe(false));
    vi.mocked(httpClient.post).mockRejectedValue(new ApiError(403, 'Old refusal'));
    await act(async () => result.current.remove('plan'));
    expect(result.current.refusal).toBe('Old refusal');
    expect(result.current.lastCommandId).toBeNull();
    const nextRead = deferred<GateSnapshot>();
    vi.mocked(httpClient.get).mockReturnValueOnce(nextRead.promise);
    rerender({
      selectedCase: selection === 'case' ? 'next-case' : caseId,
      selectedPractice: selection === 'practice' ? 'next-practice' : practiceId,
    });
    expect(result.current).toMatchObject({
      state: null, loading: true, error: null, refusal: null, lastCommandId: null,
    });
    await act(async () => nextRead.resolve(snapshot));
  });

  it.each(['case', 'practice'])('fences a late read after a %s switch', async (selection) => {
    const oldRead = deferred<GateSnapshot>();
    vi.mocked(httpClient.get).mockReturnValueOnce(oldRead.promise);
    const { result, rerender } = renderHook(
      ({ selectedCase, selectedPractice }) => useSurgeonGate(selectedCase, { practiceId: selectedPractice }),
      { initialProps: { selectedCase: caseId, selectedPractice: practiceId } },
    );
    vi.mocked(httpClient.get).mockResolvedValueOnce(receipt('synthetic', 'remove').gate);
    rerender({
      selectedCase: selection === 'case' ? 'next-case' : caseId,
      selectedPractice: selection === 'practice' ? 'next-practice' : practiceId,
    });
    await waitFor(() => expect(result.current.loading).toBe(false));
    await act(async () => oldRead.resolve(snapshot));
    expect(result.current.state).toEqual({ affirmed: false, outstanding: ['plan'] });
    expect(result.current.error).toBeNull();
  });

  it.each(['success', 'refusal'])('fences a late mutation %s after leaving and returning to a scope', async (outcome) => {
    const { result, rerender } = renderHook(
      ({ selectedPractice }) => useSurgeonGate(caseId, { practiceId: selectedPractice }),
      { initialProps: { selectedPractice: practiceId } },
    );
    await waitFor(() => expect(result.current.loading).toBe(false));
    const pending = deferred<GateCommandResult>();
    vi.mocked(httpClient.post).mockReturnValueOnce(pending.promise);
    let mutation!: Promise<void>;
    act(() => { mutation = result.current.remove('plan'); });
    rerender({ selectedPractice: 'next-practice' });
    await waitFor(() => expect(result.current.loading).toBe(false));
    rerender({ selectedPractice: practiceId });
    await waitFor(() => expect(result.current.loading).toBe(false));
    await act(async () => {
      if (outcome === 'success') pending.resolve(receipt('synthetic', 'remove'));
      else pending.reject(new ApiError(403, 'Old refusal'));
      await mutation;
    });
    expect(result.current).toMatchObject({
      state: { affirmed: true, outstanding: [] }, error: null, refusal: null, lastCommandId: null,
    });
  });

  it.each(['receipt', 'refresh'])('fences a late lookup %s after a practice switch', async (stage) => {
    const { result, rerender } = renderHook(
      ({ selectedPractice }) => useSurgeonGate(caseId, { practiceId: selectedPractice }),
      { initialProps: { selectedPractice: practiceId } },
    );
    await waitFor(() => expect(result.current.loading).toBe(false));
    const pendingReceipt = deferred<GateCommandResult>();
    const pendingRead = deferred<GateSnapshot>();
    const committed = receipt('synthetic', 'remove');
    vi.mocked(httpClient.get).mockReturnValueOnce(pendingReceipt.promise);
    let lookup!: Promise<GateCommandResult>;
    act(() => { lookup = result.current.lookupCommand(committed.commandId); });
    if (stage === 'refresh') {
      vi.mocked(httpClient.get).mockReturnValueOnce(pendingRead.promise);
      await act(async () => pendingReceipt.resolve(committed));
    }
    rerender({ selectedPractice: 'next-practice' });
    await waitFor(() => expect(result.current.loading).toBe(false));
    await act(async () => {
      if (stage === 'receipt') {
        vi.mocked(httpClient.get).mockResolvedValueOnce(committed.gate);
        pendingReceipt.resolve(committed);
      } else {
        pendingRead.resolve(committed.gate);
      }
      expect(await lookup).toEqual(committed);
    });
    expect(result.current).toMatchObject({
      state: { affirmed: true, outstanding: [] }, error: null, refusal: null, lastCommandId: null,
    });
  });

  it('clears a prior read error when the practice changes', async () => {
    vi.mocked(httpClient.get).mockRejectedValueOnce(new Error('Old read failed'));
    const { result, rerender } = renderHook(
      ({ selectedPractice }) => useSurgeonGate(caseId, { practiceId: selectedPractice }),
      { initialProps: { selectedPractice: practiceId } },
    );
    await waitFor(() => expect(result.current.error).toBe('Old read failed'));
    const nextRead = deferred<GateSnapshot>();
    vi.mocked(httpClient.get).mockReturnValueOnce(nextRead.promise);
    rerender({ selectedPractice: 'next-practice' });
    expect(result.current).toMatchObject({ state: null, error: null, loading: true });
    await act(async () => nextRead.resolve(snapshot));
  });
});

